import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  const group = new THREE.Group();
  const resources = { geoms: [], mats: [], meshes: [] };

  const colors = {
    background: '#0b0b10',
    surface: '#101015',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    hairline: '#23232b'
  };

  const W = 6.8;
  const H = 2.0;

  // Background plane with vertical gradient material
  const bgGeom = new THREE.PlaneGeometry(W, H);
  const bgMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(colors.surface),
    metalness: 0.2,
    roughness: 0.6
  });
  const bgMesh = new THREE.Mesh(bgGeom, bgMat);
  bgMesh.position.z = 0;
  group.add(bgMesh);
  resources.geoms.push(bgGeom);
  resources.mats.push(bgMat);

  // Top hairline rule
  const ruleGeom = new THREE.PlaneGeometry(W, 0.006);
  const ruleMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(colors.hairline),
    emissive: new THREE.Color(colors.hairline),
    metalness: 0.3,
    roughness: 0.5
  });
  const topRule = new THREE.Mesh(ruleGeom, ruleMat);
  topRule.position.set(0, H / 2 + 0.003, 0.01);
  group.add(topRule);
  resources.geoms.push(ruleGeom);
  resources.mats.push(ruleMat);

  // Accent bar beneath wordmark
  const accentGeom = new THREE.PlaneGeometry(0.3, 0.02);
  const accentMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.4,
    metalness: 0,
    roughness: 0.8
  });
  const accentBar = new THREE.Mesh(accentGeom, accentMat);
  accentBar.position.set(-W / 2 + 1.0, 0.1, 0.01);
  group.add(accentBar);
  resources.geoms.push(accentGeom);
  resources.mats.push(accentMat);

  // Text rendering via fontAtlas
  const texts = [
    { text: 'NOVA ATELIER', x: -W / 2 + 0.5, y: 0.6 },
    { text: 'ATELIER', x: -W / 2 + 2.5, y: 0.6 },
    { text: 'COMPANY', x: -W / 2 + 4.0, y: 0.6 },
    { text: 'LEGAL', x: -W / 2 + 5.5, y: 0.6 },
    { text: 'Features', x: -W / 2 + 2.5, y: 0.25 },
    { text: 'Collection', x: -W / 2 + 2.5, y: -0.1 },
    { text: 'Pricing', x: -W / 2 + 2.5, y: -0.45 },
    { text: 'Journal', x: -W / 2 + 4.0, y: 0.25 },
    { text: 'Visit the Atelier', x: -W / 2 + 4.0, y: -0.1 },
    { text: 'Contact', x: -W / 2 + 4.0, y: -0.45 },
    { text: 'Privacy', x: -W / 2 + 5.5, y: 0.25 },
    { text: 'Terms', x: -W / 2 + 5.5, y: -0.1 },
    { text: 'Warranty', x: -W / 2 + 5.5, y: -0.45 },
    { text: '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.', x: -W / 2 + 0.5, y: -0.85 }
  ];

  for (const item of texts) {
    try {
      const textMesh = ctx.fontAtlas.createTextMesh(item.text, {
        fontSize: 0.13,
        color: new THREE.Color(colors.paper),
        anchorX: 'left',
        anchorY: 'middle'
      });
      textMesh.position.set(item.x, item.y, 0.02);
      group.add(textMesh);
      resources.meshes.push(textMesh);
    } catch (e) {
      // Silent fail if fontAtlas unavailable
    }
  }

  // Bottom hairline rule
  const bottomRuleGeom = new THREE.PlaneGeometry(W, 0.006);
  const bottomRule = new THREE.Mesh(bottomRuleGeom, ruleMat);
  bottomRule.position.set(0, -H / 2 + 0.375 - 0.003, 0.01);
  group.add(bottomRule);
  resources.geoms.push(bottomRuleGeom);

  // Mount animation: fade-up
  gsap.from(group, {
    opacity: 0,
    y: 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    overwrite: 'auto'
  });

  // Cleanup
  group.userData.cleanup = function cleanup() {
    gsap.killTweensOf(group);
    resources.geoms.forEach(g => g?.dispose?.());
    resources.mats.forEach(m => m?.dispose?.());
  };

  group.userData.handlers = {};

  return group;
}
